# EVOLVE-BLOCK-START
def decide(observation, memory):
    """Use a safety-gated, hysteretic controller that verifies the target,
    reacquires it conservatively, and steers proportionally toward its bearing.
    """
    memory = dict(memory or {})
    previous_action = memory.get("last_action", "STOP")
    scan_direction = memory.get("scan_direction", "SCAN_LEFT")

    visible = bool(observation["target_visible"])
    bearing = float(observation["target_bearing"])
    distance = observation["target_distance_class"]
    target_confidence = float(observation["target_confidence"])
    identity_confidence = float(observation["target_identity_confidence"])
    track_age = int(observation["track_age"])
    lost_steps = int(observation["lost_steps"])
    safety_confidence = float(observation["safety_confidence"])
    closing_risk = float(observation["closing_risk"])

    def emit(action, confidence):
        memory["last_action"] = action
        return action, confidence, memory

    # Safety is an unconditional hard gate.
    if safety_confidence < 0.60 or closing_risk >= 0.75:
        memory["state"] = "STOPPED"
        return emit("STOP", 0.99)

    # Do not move on an unconfirmed or ambiguous target.
    confirmed = visible and target_confidence >= 0.55 and identity_confidence >= 0.60
    if not confirmed:
        memory["state"] = "REACQUIRE" if lost_steps > 0 else "SEARCH"
        if lost_steps <= 1:
            return emit("STOP", 0.92)
        action = scan_direction
        memory["scan_direction"] = (
            "SCAN_RIGHT" if scan_direction == "SCAN_LEFT" else "SCAN_LEFT"
        )
        return emit(action, 0.76)

    # A newly acquired track gets one stabilizing frame.
    if track_age < 2:
        memory["state"] = "VERIFY"
        return emit("SLOW_DOWN", 0.81)

    corridor_left = bool(observation["corridor_left"])
    corridor_right = bool(observation["corridor_right"])
    corridor_center = bool(observation["corridor_center"])

    # Close targets require alignment before declaring arrival.
    if distance == "near":
        heading_error = abs(float(observation["heading_error"]))
        if heading_error <= 15.0 and identity_confidence >= 0.80:
            memory["state"] = "ARRIVED"
            return emit("ARRIVED", 0.96)
        memory["state"] = "APPROACH"
        if bearing < 0.0 and corridor_left:
            return emit("VEER_LEFT", 0.89)
        if bearing > 0.0 and corridor_right:
            return emit("VEER_RIGHT", 0.89)
        if corridor_center:
            return emit("FORWARD", 0.84)
        return emit("STOP", 0.97)

    # Use a modest deadband to reduce oscillation while correcting meaningful
    # lateral error early, improving path efficiency and final alignment.
    memory["state"] = "APPROACH"
    if bearing <= -8.0 and corridor_left:
        return emit("VEER_LEFT", 0.90)
    if bearing >= 8.0 and corridor_right:
        return emit("VEER_RIGHT", 0.90)

    # Preserve a stable turn briefly when the target remains on that side.
    if -12.0 < bearing < -8.0 and previous_action == "VEER_LEFT" and corridor_left:
        return emit("VEER_LEFT", 0.86)
    if 8.0 < bearing < 12.0 and previous_action == "VEER_RIGHT" and corridor_right:
        return emit("VEER_RIGHT", 0.86)

    if corridor_center:
        return emit("FORWARD", 0.91)
    if bearing < 0.0 and corridor_left:
        return emit("VEER_LEFT", 0.83)
    if bearing > 0.0 and corridor_right:
        return emit("VEER_RIGHT", 0.83)
    if corridor_left:
        return emit("VEER_LEFT", 0.80)
    if corridor_right:
        return emit("VEER_RIGHT", 0.80)
    return emit("STOP", 0.98)
# EVOLVE-BLOCK-END
